INSERT INTO `wp_options` VALUES (105,'widget_block','a:28:{i:2;a:1:{s:7:\"content\";s:19:\"<!-- wp:search /-->\";}i:3;a:1:{s:7:\"content\";s:154:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>Recent Posts</h2><!-- /wp:heading --><!-- wp:latest-posts /--></div><!-- /wp:group -->\";}i:4;a:1:{s:7:\"content\";s:227:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>Recent Comments</h2><!-- /wp:heading --><!-- wp:latest-comments {\"displayAvatar\":false,\"displayDate\":false,\"displayExcerpt\":false} /--></div><!-- /wp:group -->\";}i:5;a:1:{s:7:\"content\";s:146:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>Archives</h2><!-- /wp:heading --><!-- wp:archives /--></div><!-- /wp:group -->\";}i:6;a:1:{s:7:\"content\";s:150:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>Categories</h2><!-- /wp:heading --><!-- wp:categories /--></div><!-- /wp:group -->\";}i:8;a:1:{s:7:\"content\";s:168:\"<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Plant Shop – Tất cả những gì bạn cần cho không gian xanh trong nhà</h3>\n<!-- /wp:heading -->\";}i:9;a:1:{s:7:\"content\";s:659:\"<!-- wp:paragraph -->\n<p>Chúng tôi là điểm đến trực tuyến lý tưởng cho những người yêu cây và muốn mang thiên nhiên vào không gian sống. Tại Plant Shop, bạn sẽ tìm thấy đa dạng các loại cây trồng trong nhà, từ cây để bàn, cây lọc không khí đến cây trang trí nội thất, cùng với các phụ kiện chăm sóc cây như chậu trồng, đất, phân bón và dụng cụ làm vườn.<br>Tất cả sản phẩm đều được giao trực tiếp từ nhà vườn của chúng tôi đến tận cửa nhà bạn, đảm bảo tươi mới và chất lượng.</p>\n<!-- /wp:paragraph -->\";}i:10;a:1:{s:7:\"content\";s:95:\"<!-- wp:paragraph -->\n<p><strong>Địa điểm cửa hàng</strong></p>\n<!-- /wp:paragraph -->\";}i:11;a:1:{s:7:\"content\";s:103:\"<!-- wp:paragraph -->\n<p>CS1: YÊn Nghĩa, Hà Đông, Hà Nội, Việt Nam</p>\n<!-- /wp:paragraph -->\";}i:12;a:1:{s:7:\"content\";s:108:\"<!-- wp:heading {\