INSERT INTO `wp_postmeta` VALUES (9455,1442,'_elementor_data','[{\"id\":\"1864537\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"57b1633\",\"elType\":\"widget\",\"settings\":{\"layout\":\"icon_text\",\"placeholder\":\"Nh\\u1eadp t\\u1eeb kh\\u00f3a ho\\u1eb7c n\\u1ed9i dung c\\u1ea7n t\\u00ecm\",\"size\":{\"unit\":\"px\",\"size\":40,\"sizes\":[]},\"input_background_color\":\"#EDEDED08\",\"border_style\":\"solid\",\"border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"border_radius\":{\"unit\":\"px\",\"size\":6,\"sizes\":[]},\"icon_size\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"button_width\":{\"unit\":\"px\",\"size\":85,\"sizes\":[]},\"text_color\":\"\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"160\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"__globals__\":{\"button_background_color\":\"globals\\/colors?id=astglobalcolor0\"}},\"elements\":[],\"widgetType\":\"hfe-search-button\"}],\"isInner\":false},{\"id\":\"27125b25\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"624c7ced\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<!-- wp:heading {\\\"level\\\":3} -->\\n<h3 class=\\\"wp-block-heading\\\"><strong>1. Ch\\u00fang t\\u00f4i l\\u00e0 ai<\\/strong><\\/h3>\\n<!-- \\/wp:heading --><!-- wp:paragraph -->\\n<p>Website c\\u1ee7a ch\\u00fang t\\u00f4i c\\u00f3 \\u0111\\u1ecba ch\\u1ec9: <strong><a class=\\\"\\\" href=\\\"http:\\/\\/planshop.com\\\">http:\\/\\/planshop.com<\\/a><\\/strong>.<br \\/>Ch\\u00fang t\\u00f4i cam k\\u1ebft b\\u1ea3o v\\u1ec7 th\\u00f4ng tin c\\u00e1 nh\\u00e2n c\\u1ee7a kh\\u00e1ch h\\u00e0ng v\\u00e0 tu\\u00e2n th\\u1ee7 c\\u00e1c quy \\u0111\\u1ecbnh v\\u1ec1 b\\u1ea3o m\\u1eadt d\\u1eef li\\u1ec7u.<\\/p>\\n<!-- \\/wp:paragraph --><!-- wp:separator --><hr class=\\\"wp-block-separator has-alpha-channel-opacity\\\" \\/><!-- \\/wp:separator --><!-- wp:heading {\\\"level\\\":3} -->\\n<h3 class=\\\"wp-block-heading\\\"><strong>2. B\\u00ecnh lu\\u1eadn<\\/strong><\\/h3>\\n<!-- \\/wp:heading --><!-- wp:paragraph -->\\n<p>Khi b\\u1ea1n \\u0111\\u1ec3 l\\u1ea1i b\\u00ecnh lu\\u1eadn tr\\u00ean website, ch\\u00fang t\\u00f4i thu th\\u1eadp th\\u00f4ng tin \\u0111\\u01b0\\u1ee3c hi\\u1ec3n th\\u1ecb trong bi\\u1ec3u m\\u1eabu b\\u00ecnh lu\\u1eadn, \\u0111\\u1ecba ch\\u1ec9 IP c\\u1ee7a b\\u1ea1n v\\u00e0 chu\\u1ed7i nh\\u1eadn d\\u1ea1ng tr\\u00ecnh duy\\u1ec7t (user agent) nh\\u1eb1m m\\u1ee5c \\u0111\\u00edch ph\\u00e1t hi\\u1ec7n v\\u00e0 ng\\u0103n ch\\u1eb7n th\\u01b0 r\\u00e1c.<\\/p>\\n<!-- \\/wp:paragraph --><!-- wp:paragraph -->\\n<p>Ngo\\u00e0i ra, m\\u1ed9t chu\\u1ed7i \\u1ea9n danh (hash) \\u0111\\u01b0\\u1ee3c t\\u1ea1o t\\u1eeb \\u0111\\u1ecba ch\\u1ec9 email c\\u1ee7a b\\u1ea1n c\\u00f3 th\\u1ec3 \\u0111\\u01b0\\u1ee3c g\\u1eedi \\u0111\\u1ebfn d\\u1ecbch v\\u1ee5 <strong>Gravatar<\\/strong> \\u0111\\u1ec3 ki\\u1ec3m tra xem b\\u1ea1n c\\u00f3 \\u0111ang s\\u1eed d\\u1ee5ng d\\u1ecbch v\\u1ee5 n\\u00e0y kh\\u00f4ng. B\\u1ea1n c\\u00f3 th\\u1ec3 tham kh\\u1ea3o ch\\u00ednh s\\u00e1ch b\\u1ea3o m\\u1eadt c\\u1ee7a Gravatar t\\u1ea1i \\u0111\\u00e2y: <a class=\\\"\\\" href=\\\"https:\\/\\/automattic.com\\/privacy\\/\\\">https:\\/\\/automattic.com\\/privacy\\/<\\/a>. Sau khi b\\u00ecnh lu\\u1eadn \\u0111\\u01b0\\u1ee3c duy\\u1ec7t, \\u1ea3nh \\u0111\\u1ea1i di\\u1ec7n c\\u1ee7a b\\u1ea1n s\\u1ebd hi\\u1ec3n th\\u1ecb c\\u00f4ng khai c\\u00f9ng v\\u1edbi b\\u00ecnh lu\\u1eadn.<\\/p>\\n<!-- \\/wp:paragraph --><!-- wp:separator --><hr class=\\\"wp-block-separator has-alpha-channel-opacity\\\" \\/><!-- \\/wp:separator --><!-- wp:heading {\\\"level\\\":3} -->\\n<h3 class=\\\"wp-block-heading\\\"><strong>3. H\\u00ecnh \\u1ea3nh &amp; N\\u1ed9i dung t\\u1ea3i l\\u00ean<\\/strong><\\/h3>\\n<!-- \\/wp:heading --><!-- wp:paragraph -->\\n<p>N\\u1ebfu b\\u1ea1n t\\u1ea3i h\\u00ecnh \\u1ea3nh l\\u00ean website, vui l\\u00f2ng tr\\u00e1nh s\\u1eed d\\u1ee5ng \\u1ea3nh c\\u00f3 ch\\u1ee9a d\\u1eef li\\u1ec7u v\\u1ecb tr\\u00ed (EXIF GPS). Kh\\u00e1ch truy c\\u1eadp kh\\u00e1c c\\u00f3 th\\u1ec3 t\\u1ea3i xu\\u1ed1ng v\\u00e0 tr\\u00edch xu\\u1ea5t th\\u00f4ng tin v\\u1ecb tr\\u00ed t\\u1eeb c\\u00e1c h\\u00ecnh \\u1ea3nh n\\u00e0y.<\\/p>\\n<!-- \\/wp:paragraph --><!-- wp:separator --><hr class=\\\"wp-block-separator has-alpha-channel-opacity\\\" \\/><!-- \\/wp:separator --><!-- wp:heading {\\\"level\\\":3} -->\\n<h3 class=\\\"wp-block-heading\\\"><strong>4. Cookie<\\/strong><\\/h3>\\n<!-- \\/wp:heading --><!-- wp:list -->\\n<ul class=\\\"wp-block-list\\\"><!-- wp:list-item -->\\n<li>N\\u1ebfu b\\u1ea1n \\u0111\\u1ec3 l\\u1ea1i b\\u00ecnh lu\\u1eadn, b\\u1ea1n c\\u00f3 th\\u1ec3 ch\\u1ecdn l\\u01b0u t\\u00ean, email v\\u00e0 website c\\u1ee7a m\\u00ecnh trong cookie \\u0111\\u1ec3 thu\\u1eadn ti\\u1ec7n cho nh\\u1eefng l\\u1ea7n b\\u00ecnh lu\\u1eadn sau. Cookie n\\u00e0y s\\u1ebd t\\u1ed3n t\\u1ea1i trong 1 n\\u0103m.<\\/li>\\n<!-- \\/wp:list-item --><!-- wp:list-item -->\\n<li>Khi truy c\\u1eadp trang \\u0111\\u0103ng nh\\u1eadp, h\\u1ec7 th\\u1ed1ng s\\u1ebd t\\u1ea1o m\\u1ed9t cookie t\\u1ea1m \\u0111\\u1ec3 ki\\u1ec3m tra vi\\u1ec7c ch\\u1ea5p nh\\u1eadn cookie tr\\u00ean tr\\u00ecnh duy\\u1ec7t. Cookie n\\u00e0y kh\\u00f4ng ch\\u1ee9a th\\u00f4ng tin c\\u00e1 nh\\u00e2n v\\u00e0 s\\u1ebd b\\u1ecb x\\u00f3a khi b\\u1ea1n \\u0111\\u00f3ng tr\\u00ecnh duy\\u1ec7t.<\\/li>\\n<!-- \\/wp:list-item --><!-- wp:list-item -->\\n<li>Khi \\u0111\\u0103ng nh\\u1eadp, ch\\u00fang t\\u00f4i l\\u01b0u cookie \\u0111\\u0103ng nh\\u1eadp trong 2 ng\\u00e0y v\\u00e0 cookie t\\u00f9y ch\\u1ecdn giao di\\u1ec7n trong 1 n\\u0103m. N\\u1ebfu ch\\u1ecdn \\u201cGhi nh\\u1edb \\u0111\\u0103ng nh\\u1eadp\\u201d, th\\u00f4ng tin \\u0111\\u0103ng nh\\u1eadp s\\u1ebd \\u0111\\u01b0\\u1ee3c l\\u01b0u trong 2 tu\\u1ea7n. Khi \\u0111\\u0103ng xu\\u1ea5t, c\\u00e1c cookie n\\u00e0y s\\u1ebd b\\u1ecb x\\u00f3a.<\\/li>\\n<!-- \\/wp:list-item --><!-- wp:list-item -->\\n<li>N\\u1ebfu b\\u1ea1n ch\\u1ec9nh s\\u1eeda ho\\u1eb7c xu\\u1ea5t b\\u1ea3n b\\u00e0i vi\\u1ebft, m\\u1ed9t cookie b\\u1ed5 sung s\\u1ebd \\u0111\\u01b0\\u1ee3c l\\u01b0u trong tr\\u00ecnh duy\\u1ec7t, ch\\u1ee9a ID c\\u1ee7a b\\u00e0i vi\\u1ebft v\\u00e0 t\\u1ef1 \\u0111\\u1ed9ng h\\u1ebft h\\u1ea1n sau 1 ng\\u00e0y.<\\/li>\\n<!-- \\/wp:list-item --><\\/ul>\\n<!-- \\/wp:list --><!-- wp:separator --><hr class=\\\"wp-block-separator has-alpha-channel-opacity\\\" \\/><!-- \\/wp:separator --><!-- wp:heading {\\\"level\\\":3} -->\\n<h3 class=\\\"wp-block-heading\\\"><strong>5. N\\u1ed9i dung nh\\u00fang t\\u1eeb website kh\\u00e1c<\\/strong><\\/h3>\\n<!-- \\/wp:heading --><!-- wp:paragraph -->\\n<p>C\\u00e1c b\\u00e0i vi\\u1ebft tr\\u00ean website c\\u00f3 th\\u1ec3 ch\\u1ee9a n\\u1ed9i dung nh\\u00fang (v\\u00ed d\\u1ee5: video, h\\u00ecnh \\u1ea3nh, b\\u00e0i vi\\u1ebft t\\u1eeb trang kh\\u00e1c). N\\u1ed9i dung nh\\u00fang ho\\u1ea1t \\u0111\\u1ed9ng gi\\u1ed1ng nh\\u01b0 khi b\\u1ea1n tr\\u1ef1c ti\\u1ebfp truy c\\u1eadp trang web g\\u1ed1c, c\\u00f3 th\\u1ec3 thu th\\u1eadp d\\u1eef li\\u1ec7u, s\\u1eed d\\u1ee5ng cookie ho\\u1eb7c theo d\\u00f5i t\\u01b0\\u01a1ng t\\u00e1c c\\u1ee7a b\\u1ea1n.<\\/p>\\n<!-- \\/wp:paragraph --><!-- wp:separator --><hr class=\\\"wp-block-separator has-alpha-channel-opacity\\\" \\/><!-- \\/wp:separator --><!-- wp:heading {\\\"level\\\":3} -->\\n<h3 class=\\\"wp-block-heading\\\"><strong>6. Chia s\\u1ebb d\\u1eef li\\u1ec7u<\\/strong><\\/h3>\\n<!-- \\/wp:heading --><!-- wp:paragraph -->\\n<p>N\\u1ebfu b\\u1ea1n y\\u00eau c\\u1ea7u \\u0111\\u1eb7t l\\u1ea1i m\\u1eadt kh\\u1ea9u, \\u0111\\u1ecba ch\\u1ec9 IP s\\u1ebd \\u0111\\u01b0\\u1ee3c \\u0111\\u01b0a v\\u00e0o email \\u0111\\u1eb7t l\\u1ea1i m\\u1eadt kh\\u1ea9u.<\\/p>\\n<!-- \\/wp:paragraph --><!-- wp:separator --><hr class=\\\"wp-block-separator has-alpha-channel-opacity\\\" \\/><!-- \\/wp:separator --><!-- wp:heading {\\\"level\\\":3} -->\\n<h3 class=\\\"wp-block-heading\\\"><strong>7. Th\\u1eddi gian l\\u01b0u tr\\u1eef d\\u1eef li\\u1ec7u<\\/strong><\\/h3>\\n<!-- \\/wp:heading --><!-- wp:list -->\\n<ul class=\\\"wp-block-list\\\"><!-- wp:list-item -->\\n<li>B\\u00ecnh lu\\u1eadn v\\u00e0 si\\u00eau d\\u1eef li\\u1ec7u s\\u1ebd \\u0111\\u01b0\\u1ee3c l\\u01b0u gi\\u1eef v\\u00f4 th\\u1eddi h\\u1ea1n \\u0111\\u1ec3 ch\\u00fang t\\u00f4i c\\u00f3 th\\u1ec3 nh\\u1eadn di\\u1ec7n v\\u00e0 ph\\u00ea duy\\u1ec7t c\\u00e1c b\\u00ecnh lu\\u1eadn ti\\u1ebfp theo m\\u1ed9t c\\u00e1ch t\\u1ef1 \\u0111\\u1ed9ng.<\\/li>\\n<!-- \\/wp:list-item --><!-- wp:list-item -->\\n<li>V\\u1edbi ng\\u01b0\\u1eddi d\\u00f9ng \\u0111\\u0103ng k\\u00fd t\\u00e0i kho\\u1ea3n, ch\\u00fang t\\u00f4i l\\u01b0u tr\\u1eef th\\u00f4ng tin c\\u00e1 nh\\u00e2n trong h\\u1ed3 s\\u01a1 ng\\u01b0\\u1eddi d\\u00f9ng. B\\u1ea1n c\\u00f3 th\\u1ec3 xem, ch\\u1ec9nh s\\u1eeda ho\\u1eb7c x\\u00f3a th\\u00f4ng tin n\\u00e0y b\\u1ea5t k\\u1ef3 l\\u00fac n\\u00e0o (ngo\\u1ea1i tr\\u1eeb t\\u00ean \\u0111\\u0103ng nh\\u1eadp). Qu\\u1ea3n tr\\u1ecb vi\\u00ean website c\\u0169ng c\\u00f3 quy\\u1ec1n xem v\\u00e0 ch\\u1ec9nh s\\u1eeda th\\u00f4ng tin \\u0111\\u00f3.<\\/li>\\n<!-- \\/wp:list-item --><\\/ul>\\n<!-- \\/wp:list --><!-- wp:separator --><hr class=\\\"wp-block-separator has-alpha-channel-opacity\\\" \\/><!-- \\/wp:separator --><!-- wp:heading {\\\"level\\\":3} -->\\n<h3 class=\\\"wp-block-heading\\\"><strong>8. Quy\\u1ec1n c\\u1ee7a b\\u1ea1n v\\u1edbi d\\u1eef li\\u1ec7u c\\u00e1 nh\\u00e2n<\\/strong><\\/h3>\\n<!-- \\/wp:heading --><!-- wp:paragraph -->\\n<p>B\\u1ea1n c\\u00f3 quy\\u1ec1n:<\\/p>\\n<!-- \\/wp:paragraph --><!-- wp:list -->\\n<ul class=\\\"wp-block-list\\\"><!-- wp:list-item -->\\n<li>Y\\u00eau c\\u1ea7u xu\\u1ea5t file d\\u1eef li\\u1ec7u c\\u00e1 nh\\u00e2n m\\u00e0 ch\\u00fang t\\u00f4i l\\u01b0u gi\\u1eef v\\u1ec1 b\\u1ea1n.<\\/li>\\n<!-- \\/wp:list-item --><!-- wp:list-item -->\\n<li>Y\\u00eau c\\u1ea7u x\\u00f3a d\\u1eef li\\u1ec7u c\\u00e1 nh\\u00e2n, tr\\u1eeb c\\u00e1c d\\u1eef li\\u1ec7u ch\\u00fang t\\u00f4i c\\u1ea7n gi\\u1eef cho m\\u1ee5c \\u0111\\u00edch qu\\u1ea3n tr\\u1ecb, ph\\u00e1p l\\u00fd ho\\u1eb7c b\\u1ea3o m\\u1eadt.<\\/li>\\n<!-- \\/wp:list-item --><\\/ul>\\n<!-- \\/wp:list --><!-- wp:separator --><hr class=\\\"wp-block-separator has-alpha-channel-opacity\\\" \\/><!-- \\/wp:separator --><!-- wp:heading {\\\"level\\\":3} -->\\n<h3 class=\\\"wp-block-heading\\\"><strong>9. N\\u01a1i d\\u1eef li\\u1ec7u \\u0111\\u01b0\\u1ee3c g\\u1eedi \\u0111\\u1ebfn<\\/strong><\\/h3>\\n<!-- \\/wp:heading --><!-- wp:paragraph -->\\n<p>B\\u00ecnh lu\\u1eadn c\\u1ee7a kh\\u00e1ch truy c\\u1eadp c\\u00f3 th\\u1ec3 \\u0111\\u01b0\\u1ee3c ki\\u1ec3m tra th\\u00f4ng qua h\\u1ec7 th\\u1ed1ng t\\u1ef1 \\u0111\\u1ed9ng ph\\u00e1t hi\\u1ec7n th\\u01b0 r\\u00e1c.<\\/p>\\n<!-- \\/wp:paragraph -->\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false}]');
