INSERT INTO `wp_postmeta` VALUES (9574,1452,'_elementor_data','[{\"id\":\"1864537\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"57b1633\",\"elType\":\"widget\",\"settings\":{\"layout\":\"icon_text\",\"placeholder\":\"Nh\\u1eadp t\\u1eeb kh\\u00f3a ho\\u1eb7c n\\u1ed9i dung c\\u1ea7n t\\u00ecm\",\"size\":{\"unit\":\"px\",\"size\":40,\"sizes\":[]},\"input_background_color\":\"#EDEDED08\",\"border_style\":\"solid\",\"border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"border_radius\":{\"unit\":\"px\",\"size\":6,\"sizes\":[]},\"icon_size\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"button_width\":{\"unit\":\"px\",\"size\":85,\"sizes\":[]},\"text_color\":\"\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"160\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"__globals__\":{\"button_background_color\":\"globals\\/colors?id=astglobalcolor0\"}},\"elements\":[],\"widgetType\":\"hfe-search-button\"}],\"isInner\":false},{\"id\":\"27125b25\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"c92998a\",\"elType\":\"widget\",\"settings\":{\"title\":\"Ch\\u00ednh s\\u00e1ch b\\u1ea3o m\\u1eadt\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"624c7ced\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<h3>1. GI\\u1edaI THI\\u1ec6U<\\/h3>\\n<p>Ch\\u00fang t\\u00f4i cam k\\u1ebft b\\u1ea3o v\\u1ec7 quy\\u1ec1n ri\\u00eang t\\u01b0 v\\u00e0 th\\u00f4ng tin c\\u00e1 nh\\u00e2n c\\u1ee7a kh\\u00e1ch h\\u00e0ng. Ch\\u00ednh s\\u00e1ch b\\u1ea3o m\\u1eadt n\\u00e0y gi\\u1ea3i th\\u00edch c\\u00e1ch ch\\u00fang t\\u00f4i thu th\\u1eadp, s\\u1eed d\\u1ee5ng, l\\u01b0u tr\\u1eef v\\u00e0 b\\u1ea3o v\\u1ec7 th\\u00f4ng tin c\\u1ee7a b\\u1ea1n khi s\\u1eed d\\u1ee5ng trang web planshop.com (sau \\u0111\\u00e2y g\\u1ecdi l\\u00e0 \\\"ch\\u00fang t\\u00f4i\\\", \\\"c\\u1ee7a ch\\u00fang t\\u00f4i\\\" ho\\u1eb7c \\\"trang web\\\").<\\/p>\\n<p>B\\u1eb1ng c\\u00e1ch truy c\\u1eadp v\\u00e0 s\\u1eed d\\u1ee5ng trang web n\\u00e0y, b\\u1ea1n \\u0111\\u1ed3ng \\u00fd v\\u1edbi c\\u00e1c \\u0111i\\u1ec1u kho\\u1ea3n trong ch\\u00ednh s\\u00e1ch b\\u1ea3o m\\u1eadt n\\u00e0y. N\\u1ebfu kh\\u00f4ng \\u0111\\u1ed3ng \\u00fd, vui l\\u00f2ng kh\\u00f4ng s\\u1eed d\\u1ee5ng d\\u1ecbch v\\u1ee5 c\\u1ee7a ch\\u00fang t\\u00f4i.<\\/p>\\n<h3>2. TH\\u00d4NG TIN CH\\u00daNG T\\u00d4I THU TH\\u1eacP<\\/h3>\\n<h4>2.1 Th\\u00f4ng tin c\\u00e1 nh\\u00e2n<\\/h4>\\n<p>Ch\\u00fang t\\u00f4i c\\u00f3 th\\u1ec3 thu th\\u1eadp c\\u00e1c th\\u00f4ng tin sau:<\\/p>\\n<p><strong>Th\\u00f4ng tin t\\u00e0i kho\\u1ea3n:<\\/strong><\\/p>\\n<ul>\\n<li>H\\u1ecd v\\u00e0 t\\u00ean \\u0111\\u1ea7y \\u0111\\u1ee7<\\/li>\\n<li>\\u0110\\u1ecba ch\\u1ec9 email<\\/li>\\n<li>S\\u1ed1 \\u0111i\\u1ec7n tho\\u1ea1i<\\/li>\\n<li>Ng\\u00e0y sinh<\\/li>\\n<li>Gi\\u1edbi t\\u00ednh<\\/li>\\n<li>M\\u1eadt kh\\u1ea9u (\\u0111\\u01b0\\u1ee3c m\\u00e3 h\\u00f3a)<\\/li>\\n<\\/ul>\\n<p><strong>Th\\u00f4ng tin giao h\\u00e0ng v\\u00e0 thanh to\\u00e1n:<\\/strong><\\/p>\\n<ul>\\n<li>\\u0110\\u1ecba ch\\u1ec9 giao h\\u00e0ng v\\u00e0 thanh to\\u00e1n<\\/li>\\n<li>Th\\u00f4ng tin th\\u1ebb t\\u00edn d\\u1ee5ng\\/ghi n\\u1ee3 (ch\\u1ec9 l\\u01b0u 4 s\\u1ed1 cu\\u1ed1i)<\\/li>\\n<li>L\\u1ecbch s\\u1eed \\u0111\\u01a1n h\\u00e0ng<\\/li>\\n<li>Ph\\u01b0\\u01a1ng th\\u1ee9c thanh to\\u00e1n \\u01b0a th\\u00edch<\\/li>\\n<li>Th\\u00f4ng tin xu\\u1ea5t h\\u00f3a \\u0111\\u01a1n (n\\u1ebfu c\\u00f3)<\\/li>\\n<\\/ul>\\n<p><strong>Th\\u00f4ng tin li\\u00ean l\\u1ea1c:<\\/strong><\\/p>\\n<ul>\\n<li>N\\u1ed9i dung tin nh\\u1eafn, email li\\u00ean h\\u1ec7<\\/li>\\n<li>Ph\\u1ea3n h\\u1ed3i kh\\u1ea3o s\\u00e1t kh\\u00e1ch h\\u00e0ng<\\/li>\\n<li>\\u0110\\u00e1nh gi\\u00e1 v\\u00e0 nh\\u1eadn x\\u00e9t s\\u1ea3n ph\\u1ea9m<\\/li>\\n<li>Th\\u00f4ng tin h\\u1ed7 tr\\u1ee3 kh\\u00e1ch h\\u00e0ng<\\/li>\\n<\\/ul>\\n<h4>2.2 Th\\u00f4ng tin k\\u1ef9 thu\\u1eadt<\\/h4>\\n<p><strong>Th\\u00f4ng tin thi\\u1ebft b\\u1ecb v\\u00e0 tr\\u00ecnh duy\\u1ec7t:<\\/strong><\\/p>\\n<ul>\\n<li>\\u0110\\u1ecba ch\\u1ec9 IP<\\/li>\\n<li>Lo\\u1ea1i thi\\u1ebft b\\u1ecb v\\u00e0 h\\u1ec7 \\u0111i\\u1ec1u h\\u00e0nh<\\/li>\\n<li>Tr\\u00ecnh duy\\u1ec7t web v\\u00e0 phi\\u00ean b\\u1ea3n<\\/li>\\n<li>\\u0110\\u1ed9 ph\\u00e2n gi\\u1ea3i m\\u00e0n h\\u00ecnh<\\/li>\\n<li>M\\u00fai gi\\u1edd v\\u00e0 ng\\u00f4n ng\\u1eef<\\/li>\\n<\\/ul>\\n<p><strong>D\\u1eef li\\u1ec7u s\\u1eed d\\u1ee5ng website:<\\/strong><\\/p>\\n<ul>\\n<li>Trang web \\u0111\\u01b0\\u1ee3c truy c\\u1eadp<\\/li>\\n<li>Th\\u1eddi gian truy c\\u1eadp v\\u00e0 th\\u1eddi l\\u01b0\\u1ee3ng<\\/li>\\n<li>\\u0110\\u01b0\\u1eddng d\\u1eabn click v\\u00e0 h\\u00e0nh vi duy\\u1ec7t<\\/li>\\n<li>T\\u1eeb kh\\u00f3a t\\u00ecm ki\\u1ebfm<\\/li>\\n<li>S\\u1ea3n ph\\u1ea9m \\u0111\\u00e3 xem v\\u00e0 mua<\\/li>\\n<li>Gi\\u1ecf h\\u00e0ng b\\u1ecb b\\u1ecf d\\u1edf<\\/li>\\n<\\/ul>\\n<p><strong>Cookies v\\u00e0 c\\u00f4ng ngh\\u1ec7 theo d\\u00f5i:<\\/strong><\\/p>\\n<ul>\\n<li>Cookies ch\\u1ee9c n\\u0103ng<\\/li>\\n<li>Cookies hi\\u1ec7u su\\u1ea5t<\\/li>\\n<li>Cookies qu\\u1ea3ng c\\u00e1o<\\/li>\\n<li>Web beacons v\\u00e0 pixel tracking<\\/li>\\n<li>Local storage v\\u00e0 session storage<\\/li>\\n<\\/ul>\\n<h4>2.3 Th\\u00f4ng tin t\\u1eeb m\\u1ea1ng x\\u00e3 h\\u1ed9i<\\/h4>\\n<p>N\\u1ebfu b\\u1ea1n \\u0111\\u0103ng nh\\u1eadp qua m\\u1ea1ng x\\u00e3 h\\u1ed9i, ch\\u00fang t\\u00f4i c\\u00f3 th\\u1ec3 nh\\u1eadn:<\\/p>\\n<ul>\\n<li>Th\\u00f4ng tin h\\u1ed3 s\\u01a1 c\\u00f4ng khai<\\/li>\\n<li>\\u0110\\u1ecba ch\\u1ec9 email li\\u00ean k\\u1ebft<\\/li>\\n<li>Danh s\\u00e1ch b\\u1ea1n b\\u00e8 (n\\u1ebfu \\u0111\\u01b0\\u1ee3c ph\\u00e9p)<\\/li>\\n<li>S\\u1edf th\\u00edch v\\u00e0 ho\\u1ea1t \\u0111\\u1ed9ng<\\/li>\\n<\\/ul>\\n<h3>3. C\\u00c1CH CH\\u00daNG T\\u00d4I THU TH\\u1eacP TH\\u00d4NG TIN<\\/h3>\\n<h4>3.1 Thu th\\u1eadp tr\\u1ef1c ti\\u1ebfp<\\/h4>\\n<ul>\\n<li>Khi b\\u1ea1n t\\u1ea1o t\\u00e0i kho\\u1ea3n<\\/li>\\n<li>Khi \\u0111\\u1eb7t h\\u00e0ng v\\u00e0 thanh to\\u00e1n<\\/li>\\n<li>Khi \\u0111\\u0103ng k\\u00fd nh\\u1eadn tin<\\/li>\\n<li>Khi li\\u00ean h\\u1ec7 h\\u1ed7 tr\\u1ee3<\\/li>\\n<li>Khi tham gia kh\\u1ea3o s\\u00e1t ho\\u1eb7c ch\\u01b0\\u01a1ng tr\\u00ecnh khuy\\u1ebfn m\\u00e3i<\\/li>\\n<li>Khi \\u0111\\u1ec3 l\\u1ea1i \\u0111\\u00e1nh gi\\u00e1 s\\u1ea3n ph\\u1ea9m<\\/li>\\n<\\/ul>\\n<h4>3.2 Thu th\\u1eadp t\\u1ef1 \\u0111\\u1ed9ng<\\/h4>\\n<ul>\\n<li>Th\\u00f4ng qua cookies v\\u00e0 c\\u00f4ng ngh\\u1ec7 t\\u01b0\\u01a1ng t\\u1ef1<\\/li>\\n<li>T\\u1eeb c\\u00e1c c\\u00f4ng c\\u1ee5 ph\\u00e2n t\\u00edch web (Google Analytics, etc.)<\\/li>\\n<li>Qua t\\u00edch h\\u1ee3p m\\u1ea1ng x\\u00e3 h\\u1ed9i<\\/li>\\n<li>T\\u1eeb c\\u00e1c \\u0111\\u1ed1i t\\u00e1c c\\u00f4ng ngh\\u1ec7<\\/li>\\n<\\/ul>\\n<h4>3.3 Thu th\\u1eadp t\\u1eeb b\\u00ean th\\u1ee9 ba<\\/h4>\\n<ul>\\n<li>D\\u1ecbch v\\u1ee5 x\\u00e1c minh danh t\\u00ednh<\\/li>\\n<li>C\\u01a1 s\\u1edf d\\u1eef li\\u1ec7u marketing<\\/li>\\n<li>\\u0110\\u1ed1i t\\u00e1c logistics v\\u00e0 v\\u1eadn chuy\\u1ec3n<\\/li>\\n<li>Nh\\u00e0 cung c\\u1ea5p d\\u1ecbch v\\u1ee5 thanh to\\u00e1n<\\/li>\\n<\\/ul>\\n<h3>4. M\\u1ee4C \\u0110\\u00cdCH S\\u1eec D\\u1ee4NG TH\\u00d4NG TIN<\\/h3>\\n<h4>4.1 Cung c\\u1ea5p d\\u1ecbch v\\u1ee5<\\/h4>\\n<ul>\\n<li>X\\u1eed l\\u00fd v\\u00e0 ho\\u00e0n th\\u00e0nh \\u0111\\u01a1n h\\u00e0ng<\\/li>\\n<li>Qu\\u1ea3n l\\u00fd t\\u00e0i kho\\u1ea3n kh\\u00e1ch h\\u00e0ng<\\/li>\\n<li>Cung c\\u1ea5p d\\u1ecbch v\\u1ee5 h\\u1ed7 tr\\u1ee3 kh\\u00e1ch h\\u00e0ng<\\/li>\\n<li>X\\u1eed l\\u00fd thanh to\\u00e1n v\\u00e0 ho\\u00e0n ti\\u1ec1n<\\/li>\\n<li>Giao h\\u00e0ng v\\u00e0 theo d\\u00f5i \\u0111\\u01a1n h\\u00e0ng<\\/li>\\n<\\/ul>\\n<h4>4.2 C\\u1ea3i thi\\u1ec7n d\\u1ecbch v\\u1ee5<\\/h4>\\n<ul>\\n<li>Ph\\u00e2n t\\u00edch h\\u00e0nh vi ng\\u01b0\\u1eddi d\\u00f9ng<\\/li>\\n<li>C\\u1ea3i thi\\u1ec7n giao di\\u1ec7n v\\u00e0 tr\\u1ea3i nghi\\u1ec7m<\\/li>\\n<li>Ph\\u00e1t tri\\u1ec3n s\\u1ea3n ph\\u1ea9m v\\u00e0 d\\u1ecbch v\\u1ee5 m\\u1edbi<\\/li>\\n<li>T\\u1ed1i \\u01b0u h\\u00f3a hi\\u1ec7u su\\u1ea5t website<\\/li>\\n<li>Nghi\\u00ean c\\u1ee9u th\\u1ecb tr\\u01b0\\u1eddng<\\/li>\\n<\\/ul>\\n<h4>4.3 Marketing v\\u00e0 li\\u00ean l\\u1ea1c<\\/h4>\\n<ul>\\n<li>G\\u1eedi th\\u00f4ng tin khuy\\u1ebfn m\\u00e3i<\\/li>\\n<li>Newsletter v\\u00e0 th\\u00f4ng tin s\\u1ea3n ph\\u1ea9m m\\u1edbi<\\/li>\\n<li>Ch\\u01b0\\u01a1ng tr\\u00ecnh kh\\u00e1ch h\\u00e0ng th\\u00e2n thi\\u1ebft<\\/li>\\n<li>Qu\\u1ea3ng c\\u00e1o \\u0111\\u01b0\\u1ee3c c\\u00e1 nh\\u00e2n h\\u00f3a<\\/li>\\n<li>Remarketing v\\u00e0 retargeting<\\/li>\\n<\\/ul>\\n<h4>4.4 Tu\\u00e2n th\\u1ee7 ph\\u00e1p lu\\u1eadt<\\/h4>\\n<ul>\\n<li>\\u0110\\u00e1p \\u1ee9ng y\\u00eau c\\u1ea7u ph\\u00e1p l\\u00fd<\\/li>\\n<li>Ph\\u00f2ng ch\\u1ed1ng gian l\\u1eadn<\\/li>\\n<li>B\\u1ea3o m\\u1eadt v\\u00e0 an to\\u00e0n th\\u00f4ng tin<\\/li>\\n<li>Gi\\u1ea3i quy\\u1ebft tranh ch\\u1ea5p<\\/li>\\n<li>Ki\\u1ec3m to\\u00e1n v\\u00e0 b\\u00e1o c\\u00e1o<\\/li>\\n<\\/ul>\\n<h3>5. CHIA S\\u1eba TH\\u00d4NG TIN V\\u1edaI B\\u00caN TH\\u1ee8 BA<\\/h3>\\n<h4>5.1 \\u0110\\u1ed1i t\\u00e1c d\\u1ecbch v\\u1ee5<\\/h4>\\n<p><strong>Nh\\u00e0 cung c\\u1ea5p d\\u1ecbch v\\u1ee5 thanh to\\u00e1n:<\\/strong><\\/p>\\n<ul>\\n<li>PayPal, VNPay, MoMo<\\/li>\\n<li>Ch\\u1ec9 chia s\\u1ebb th\\u00f4ng tin c\\u1ea7n thi\\u1ebft \\u0111\\u1ec3 x\\u1eed l\\u00fd thanh to\\u00e1n<\\/li>\\n<li>Tu\\u00e2n th\\u1ee7 chu\\u1ea9n b\\u1ea3o m\\u1eadt PCI DSS<\\/li>\\n<\\/ul>\\n<p><strong>\\u0110\\u1ed1i t\\u00e1c v\\u1eadn chuy\\u1ec3n:<\\/strong><\\/p>\\n<ul>\\n<li>Viettel Post, GHTK, J&amp;T Express<\\/li>\\n<li>Th\\u00f4ng tin giao h\\u00e0ng v\\u00e0 li\\u00ean l\\u1ea1c<\\/li>\\n<li>Theo d\\u00f5i v\\u00e0 c\\u1eadp nh\\u1eadt tr\\u1ea1ng th\\u00e1i \\u0111\\u01a1n h\\u00e0ng<\\/li>\\n<\\/ul>\\n<p><strong>D\\u1ecbch v\\u1ee5 c\\u00f4ng ngh\\u1ec7:<\\/strong><\\/p>\\n<ul>\\n<li>Hosting v\\u00e0 cloud storage<\\/li>\\n<li>Email marketing (MailChimp, SendGrid)<\\/li>\\n<li>Analytics (Google Analytics, Facebook Pixel)<\\/li>\\n<li>Chatbot v\\u00e0 customer support<\\/li>\\n<\\/ul>\\n<h4>5.2 Y\\u00eau c\\u1ea7u ph\\u00e1p l\\u00fd<\\/h4>\\n<p>Ch\\u00fang t\\u00f4i c\\u00f3 th\\u1ec3 chia s\\u1ebb th\\u00f4ng tin khi:<\\/p>\\n<ul>\\n<li>C\\u00f3 y\\u00eau c\\u1ea7u t\\u1eeb c\\u01a1 quan ph\\u00e1p lu\\u1eadt<\\/li>\\n<li>C\\u1ea7n thi\\u1ebft \\u0111\\u1ec3 tu\\u00e2n th\\u1ee7 lu\\u1eadt ph\\u00e1p<\\/li>\\n<li>B\\u1ea3o v\\u1ec7 quy\\u1ec1n l\\u1ee3i v\\u00e0 an to\\u00e0n c\\u1ee7a c\\u00f4ng ty<\\/li>\\n<li>Ph\\u00f2ng ch\\u1ed1ng gian l\\u1eadn v\\u00e0 ho\\u1ea1t \\u0111\\u1ed9ng b\\u1ea5t h\\u1ee3p ph\\u00e1p<\\/li>\\n<\\/ul>\\n<h4>5.3 Chuy\\u1ec3n nh\\u01b0\\u1ee3ng kinh doanh<\\/h4>\\n<p>Trong tr\\u01b0\\u1eddng h\\u1ee3p s\\u00e1p nh\\u1eadp, mua b\\u00e1n ho\\u1eb7c chuy\\u1ec3n nh\\u01b0\\u1ee3ng t\\u00e0i s\\u1ea3n, th\\u00f4ng tin kh\\u00e1ch h\\u00e0ng c\\u00f3 th\\u1ec3 \\u0111\\u01b0\\u1ee3c chuy\\u1ec3n giao v\\u1edbi c\\u00e1c bi\\u1ec7n ph\\u00e1p b\\u1ea3o m\\u1eadt th\\u00edch h\\u1ee3p.<\\/p>\\n<h4>5.4 Th\\u00f4ng tin kh\\u00f4ng nh\\u1eadn d\\u1ea1ng<\\/h4>\\n<p>Ch\\u00fang t\\u00f4i c\\u00f3 th\\u1ec3 chia s\\u1ebb d\\u1eef li\\u1ec7u t\\u1ed5ng h\\u1ee3p, \\u1ea9n danh \\u0111\\u1ec3:<\\/p>\\n<ul>\\n<li>Ph\\u00e2n t\\u00edch th\\u1ecb tr\\u01b0\\u1eddng v\\u00e0 xu h\\u01b0\\u1edbng<\\/li>\\n<li>Nghi\\u00ean c\\u1ee9u h\\u1ecdc thu\\u1eadt<\\/li>\\n<li>B\\u00e1o c\\u00e1o ng\\u00e0nh<\\/li>\\n<li>C\\u1ea3i thi\\u1ec7n d\\u1ecbch v\\u1ee5 chung<\\/li>\\n<\\/ul>\\n<h3>6. B\\u1ea2O M\\u1eacT V\\u00c0 L\\u01afU TR\\u1eee TH\\u00d4NG TIN<\\/h3>\\n<h4>6.1 Bi\\u1ec7n ph\\u00e1p b\\u1ea3o m\\u1eadt k\\u1ef9 thu\\u1eadt<\\/h4>\\n<p><strong>M\\u00e3 h\\u00f3a d\\u1eef li\\u1ec7u:<\\/strong><\\/p>\\n<ul>\\n<li>SSL\\/TLS cho truy\\u1ec1n t\\u1ea3i d\\u1eef li\\u1ec7u<\\/li>\\n<li>M\\u00e3 h\\u00f3a AES-256 cho l\\u01b0u tr\\u1eef<\\/li>\\n<li>Hashing cho m\\u1eadt kh\\u1e