INSERT INTO `wp_posts` VALUES (14,1,'2025-07-12 20:27:32','2025-07-12 20:27:32','{\"fields\":{\"1\":{\"id\":\"1\",\"type\":\"name\",\"label\":\"Name\",\"format\":\"simple\",\"description\":\"\",\"required\":\"1\",\"size\":\"large\",\"simple_placeholder\":\"\",\"simple_default\":\"\",\"first_placeholder\":\"\",\"first_default\":\"\",\"middle_placeholder\":\"\",\"middle_default\":\"\",\"last_placeholder\":\"\",\"last_default\":\"\",\"css\":\"\"},\"2\":{\"id\":\"2\",\"type\":\"email\",\"label\":\"Email\",\"description\":\"\",\"required\":\"1\",\"size\":\"large\",\"placeholder\":\"\",\"confirmation_placeholder\":\"\",\"default_value\":false,\"filter_type\":\"\",\"allowlist\":\"\",\"denylist\":\"\",\"css\":\"\"},\"4\":{\"id\":\"4\",\"type\":\"email\",\"label\":\"Phone\",\"description\":\"\",\"required\":\"1\",\"size\":\"large\",\"placeholder\":\"\",\"confirmation_placeholder\":\"\",\"default_value\":false,\"filter_type\":\"\",\"allowlist\":\"\",\"denylist\":\"\",\"css\":\"\"},\"3\":{\"id\":\"3\",\"type\":\"textarea\",\"label\":\"Message\",\"description\":\"\",\"size\":\"medium\",\"placeholder\":\"\",\"limit_count\":\"1\",\"limit_mode\":\"characters\",\"default_value\":\"\",\"css\":\"\"}},\"id\":13,\"field_id\":5,\"settings\":{\"form_title\":\"Simple Contact Form\",\"form_desc\":\"\",\"submit_text\":\"Submit\",\"submit_text_processing\":\"Sending...\",\"form_class\":\"\",\"submit_class\":\"\",\"ajax_submit\":\"1\",\"notification_enable\":\"1\",\"notifications\":{\"1\":{\"email\":\"{admin_email}\",\"subject\":\"New Entry: Simple Contact Form\",\"sender_name\":\"Urban Jungle Co\",\"sender_address\":\"{admin_email}\",\"replyto\":\"{field_id=\\\"2\\\"}\",\"message\":\"{all_fields}\",\"template\":\"\"}},\"confirmations\":{\"1\":{\"type\":\"message\",\"message\":\"<p>Thanks for contacting us! We will be in touch with you shortly.<\\/p>\",\"message_scroll\":\"1\",\"page\":\"15\",\"redirect\":\"\"}},\"antispam_v3\":\"1\",\"anti_spam\":{\"time_limit\":{\"enable\":\"1\",\"duration\":\"2\"},\"filtering_store_spam\":\"1\"},\"form_tags\":[],\"store_spam_entries\":\"0\"},\"search_terms\":\"\",\"meta\":{\"template\":\"simple-contact-form-template\"}}','Simple Contact Form','','inherit','closed','closed','','13-revision-v1','','','2025-07-12 20:27:32','2025-07-12 20:27:32','',13,'http://planshop.local/?p=14',0,'revision','',0);
