INSERT INTO `wp_posts` VALUES (585,1,'2025-07-15 06:09:55','2025-07-14 23:09:55','','Trầu Bà Lá Xẻ - Monstera Split-Leaf','<strong>Tên khoa học:</strong> Philodendron Monstera deliciosa\r\n<strong>Tên thường gọi:</strong> Cây phô mai Thụy Sĩ hay cây bão, cây salad trái cây, Monstera\r\n<strong>Mô tả:</strong> Có nguồn gốc từ các khu rừng nhiệt đới ở Trung và Nam Mỹ, loài cây này có lá hình trái tim bóng, phát triển các đường xẻ độc đáo khi trưởng thành. Đây là một loại dây leo lâu năm, thường xanh, có lẽ được biết đến nhiều nhất với những chiếc lá lớn có lỗ trên thân cây dày và rễ khí sinh dài như dây thừng.\r\n<div class=\"locationLine\">\r\n<div class=\"location\">CA Greenhouse 293</div>\r\n</div>\r\n<div class=\"locationLine\">\r\n<div class=\"location\">FL Greenhouse 299</div>\r\n</div>','publish','open','closed','','monstera-split-leaf','','','2025-07-16 16:55:44','2025-07-16 09:55:44','',0,'http://planshop.local/?post_type=product&#038;p=585',0,'product','',0);
