INSERT INTO `wp_posts` VALUES (927,1,'2025-07-16 18:14:03','2025-07-16 11:14:03','		<div data-elementor-type=\"wp-page\" data-elementor-id=\"6\" class=\"elementor elementor-6\">\n				<div class=\"elementor-element elementor-element-69962d4 e-flex e-con-boxed e-con e-parent\" data-id=\"69962d4\" data-element_type=\"container\" data-settings=\"{&quot;background_background&quot;:&quot;classic&quot;}\">\n					<div class=\"e-con-inner\">\n		<div class=\"elementor-element elementor-element-3e1f12a e-con-full e-flex e-con e-child\" data-id=\"3e1f12a\" data-element_type=\"container\">\n				<div class=\"elementor-element elementor-element-c39df12 elementor-widget elementor-widget-text-editor\" data-id=\"c39df12\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n				<div class=\"elementor-widget-container\">\n									100+ projects across the globe								</div>\n				</div>\n				<div class=\"elementor-element elementor-element-8066e8f elementor-widget elementor-widget-heading\" data-id=\"8066e8f\" data-element_type=\"widget\" data-widget_type=\"heading.default\">\n				<div class=\"elementor-widget-container\">\n					<h1 class=\"elementor-heading-title elementor-size-default\">Women In Action</h1>				</div>\n				</div>\n				<div class=\"elementor-element elementor-element-46c4360 elementor-widget elementor-widget-heading\" data-id=\"46c4360\" data-element_type=\"widget\" data-widget_type=\"heading.default\">\n				<div class=\"elementor-widget-container\">\n					<h5 class=\"elementor-heading-title elementor-size-default\">We work towards ensuring a life free from inequality and discrimination for every woman. </h5>				</div>\n				</div>\n				<div class=\"elementor-element elementor-element-92216ca elementor-align-center elementor-widget elementor-widget-button\" data-id=\"92216ca\" data-element_type=\"widget\" data-widget_type=\"button.default\">\n				<div class=\"elementor-widget-container\">\n									<div class=\"elementor-button-wrapper\">\n					<a cl