INSERT INTO `wp_posts` VALUES (1469,1,'2025-08-19 09:36:41','2025-08-19 02:36:41','<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🌿 CHÚNG TÔI LUÔN SẴN SÀNG HỖ TRỢ BẠN</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Tại <strong>PlanShop</strong>, chúng tôi cam kết mang đến cho bạn trải nghiệm mua sắm tuyệt vời nhất. Đội ngũ tư vấn viên giàu kinh nghiệm và đam mê cây cảnh của chúng tôi luôn sẵn sàng hỗ trợ bạn 24/7.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">📞 THÔNG TIN LIÊN HỆ</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Hotline Chăm Sóc Khách Hàng</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>📱 Hotline:</strong> 1900 XXX XXX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>⏰ Thời gian:</strong> 8:00 - 20:00 (Thứ 2 - Chủ nhật)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🎯 Hỗ trợ:</strong> Đặt hàng, tư vấn sản phẩm, theo dõi đơn hàng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Hotline Kỹ Thuật - Tư Vấn Chăm Sóc Cây</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>📱 Hotline:</strong> 0909 XXX XXX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>⏰ Thời gian:</strong> 8:00 - 22:00 (Hàng ngày)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🌱 Chuyên về:</strong> Chăm sóc cây, điều trị bệnh, tư vấn kỹ thuật</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Email Hỗ Trợ</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>📧 Tổng đài:</strong> support@planshop.vn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📧 Tư vấn kỹ thuật:</strong> tech@planshop.vn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📧 Hợp tác kinh doanh:</strong> business@planshop.vn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📧 Khiếu nại:</strong> complaint@planshop.vn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>⏱️ Thời gian phản hồi:</strong> Trong vòng 4 giờ (giờ hành chính)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🏢 HỆ THỐNG CỬA HÀNG</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Cửa Hàng Chính - Hà Nội</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>📍 Địa chỉ:</strong> Yên Nghĩa - Hà Đông - Hà Nội - Việt Nam</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>⏰ Giờ mở cửa:</strong> 8:00 - 19:00 (Thứ 2 - Chủ nhật)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📞 Điện thoại:</strong> 024.XXXX.XXXX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🚗 Đỗ xe:</strong> Có khu vực đỗ xe rộng rãi</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🌿 Dịch vụ:</strong> Tư vấn trực tiếp, chăm sóc cây tại chỗ</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">💬 KÊNH HỖ TRỢ TRỰC TUYẾN</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Chat Trực Tuyến</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>🖥️ Website:</strong> Góc phải màn hình trên planshop.vn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>⏰ Hoạt động:</strong> 24/7 với AI ChatBot + nhân viên (8:00-20:00)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🎯 Hỗ trợ:</strong> Tư vấn nhanh, giải đáp thắc mắc tức thì</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Mạng Xã Hội</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>📘 Facebook:</strong> facebook.com/planshop.vietnam<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Tin tức, khuyến mãi, cộng đồng yêu cây</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📸 Instagram:</strong> @planshop_vietnam<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Hình ảnh cây đẹp, tips chăm sóc</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📺 YouTube:</strong> PlanShop Vietnam<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Video hướng dẫn, livestream tư vấn</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>💬 Zalo OA:</strong> Tìm kiếm \"PlanShop\"<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Tư vấn 1-1, nhận thông báo đơn hàng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">📋 CÁC DỊCH VỤ HỖ TRỢ</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🌱 Tư Vấn Chăm Sóc Cây</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Miễn phí:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Tư vấn chọn cây phù hợp với không gian</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hướng dẫn chăm sóc cơ bản qua điện thoại/chat</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Chẩn đoán bệnh cây qua hình ảnh</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Group Facebook \"Cộng đồng người yêu cây PlanShop\"</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Có phí:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Tư vấn trực tiếp tại nhà (200.000đ/lần, miễn phí trong 10km)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Dịch vụ chăm sóc cây định kỳ</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Thiết kế sân vườn, ban công</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Khóa học chăm sóc cây nâng cao</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>📦 Dịch Vụ Giao Hàng</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Nội thành Hà Nội/TP.HCM:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Giao hàng trong ngày (đặt trước 14:00)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Phí ship: 30.000đ (miễn phí đơn >500.000đ)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Nhân viên chuyên nghiệp, có kinh nghiệm vận chuyển cây</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Toàn quốc:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Thời gian: 2-5 ngày tùy khu vực</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Đóng gói chuyên nghiệp, đảm bảo cây an toàn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bảo hiểm 100% giá trị đơn hàng</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Theo dõi hành trình 24/7</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>🔄 Hậu Mãi &amp; Bảo Hành</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Bảo hành cây 7 ngày</strong> (chết do lỗi vận chuyển/chất lượng)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Hỗ trợ kỹ thuật 3 tháng</strong> miễn phí</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Đổi trả dụng cụ trong 15 ngày</strong> (còn nguyên seal)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Sửa chữa thiết bị</strong> có bảo hành chính hãng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🎯 CÁC TRƯỜNG HỢP LIÊN HỆ</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🛒 Mua Hàng &amp; Đặt Hàng</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Liên hệ khi:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Cần tư vấn chọn cây phù hợp</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Đặt hàng số lượng lớn (>10 cây)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Yêu cầu cây đặc biệt/hiếm</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cần báo giá cho doanh nghiệp</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Thông tin cần cung cấp:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Không gian trồng cây (trong/ngoài nhà, diện tích)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Điều kiện ánh sáng</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Kinh nghiệm chăm sóc cây</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ngân sách dự kiến</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🌿 Tư Vấn Kỹ Thuật</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Hỗ trợ về:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Cây vàng lá, héo, rụng lá</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Sâu bệnh, nấm mốc</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cách bón phân, tưới nước đúng cách</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tạo dáng, cắt tỉa cây</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Chuẩn bị trước:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Chụp ảnh cây từ nhiều góc độ</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mô tả triệu chứng chi tiết</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Thông tin về cách chăm sóc gần đây</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Điều kiện môi trường (ánh sáng, độ ẩm)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>📞 Khiếu Nại &amp; Góp Ý</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Khi nào cần liên hệ:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Sản phẩm không đúng mô tả</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cây chết/bị bệnh khi nhận hàng</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Dịch vụ không như mong đợi</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Muốn góp ý cải thiện</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Thông tin cần có:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Mã đơn hàng</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ảnh chụp sản phẩm</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mô tả vấn đề cụ thể</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Thời gian phát hiện sự cố</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🤝 HỢP TÁC KINH DOANH</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>👥 Đối Tác Phân Phối</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Chúng tôi tìm kiếm:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Cửa hàng cây cảnh địa phương</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Siêu thị, trung tâm thương mại</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Công ty landscaping</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Nhà thầu xây dựng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Ưu đãi đối tác:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Giá sỉ cạnh tranh</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hỗ trợ marketing</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Đào tạo nhân viên</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bảo hành mở rộng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🏢 Khách Hàng Doanh Nghiệp</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Dịch vụ B2B:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Thiết kế không gian xanh văn phòng</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cung cấp cây số lượng lớn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hợp đồng chăm sóc dài hạn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tư vấn phong thủy doanh nghiệp</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Quy trình hợp tác:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Khảo sát nhu cầu và không gian</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Đề xuất phương án và báo giá</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ký hợp đồng và triển khai</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bàn giao và hướng dẫn chăm sóc</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hỗ trợ bảo hành và maintain</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">📅 ĐẶT LỊCH HẸN</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🏠 Tư Vấn Tại Nhà</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Đặt lịch:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Online: planshop.vn/dat-lich-tu-van</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hotline: 1900 XXX XXX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Zalo: Nhắn tin \"Đặt lịch tư vấn\"</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Thời gian:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Thứ 2 - Thứ 6: 8:00 - 17:00</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Thứ 7 - Chủ nhật: 8:00 - 12:00</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Đặt trước ít nhất 24 giờ</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🏢 Thăm Quan Showroom</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Không cần đặt lịch:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Ghé thăm trực tiếp trong giờ mở cửa</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tự do tham quan và tư vấn</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Đặt lịch VIP (khuyến khích):</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Được tư vấn riêng 1-1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ưu tiên phục vụ</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Miễn phí nước uống và wifi</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">❓ CÂU HỎI THƯỜNG GẶP</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Sản Phẩm</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Q: Cây của PlanShop có được bảo hành không?</strong> A: Có, tất cả cây cảnh được bảo hành 7 ngày chết do lỗi vận chuyển hoặc chất lượng ban đầu. Hỗ trợ tư vañn chăm sóc miễn phí trong 3 tháng.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Q: Làm sao biết cây phù hợp với không gian nhà tôi?</strong> A: Liên hệ hotline tư vấn kỹ thuật, gửi ảnh không gian và chúng tôi sẽ tư vấn cây phù hợp nhất. Hoặc sử dụng tool \"Tìm cây phù hợp\" trên website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Giao Hàng</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Q: Cây có bị hư hại trong quá trình vận chuyển không?</strong> A: Chúng tôi có quy trình đóng gói chuyên nghiệp và bảo hiểm 100% giá trị. Nếu có hư hỏng, chúng tôi hoàn tiền hoặc giao cây mới miễn phí.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Q: Tôi có thể theo dõi đơn hàng như thế nào?</strong> A: SMS tự động, app mobile, hoặc nhập mã vận đơn trên website để theo dõi real-time.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Thanh Toán</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Q: PlanShop hỗ trợ những hình thức thanh toán nào?</strong> A: COD, chuyển khoản, thẻ tín dụng, ví điện tử (MoMo, ZaloPay, VNPay), trả góp qua thẻ tín dụng.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🏆 CAM KẾT CỦA PLANSHOP</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Chất Lượng</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>✅ Cây khỏe mạnh, không mang mầm bệnh</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✅ Nguồn gốc rõ ràng từ các vườn ươm uy tín</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✅ Đóng gói chuyên nghiệp, bảo vệ tối đa</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✅ Bảo hành rõ ràng, không \"lươn lẹo\"</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Dịch Vụ</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>⭐ Tư vấn tận tình, chuyên nghiệp</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>⭐ Giao hàng đúng hẹn, an toàn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>⭐ Hỗ trợ sau bán hàng chu đáo</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>⭐ Giải quyết khiếu nại nhanh chóng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Giá Cả</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>💰 Giá cả hợp lý, cạnh tranh</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>💰 Không phát sinh phí ẩn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>💰 Khuyến mãi thường xuyên</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>💰 Tích điểm đổi quà hấp dẫn</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🌟 ĐÁNH GIÁ TỪ KHÁCH HÀNG</h3>\n<!-- /wp:heading -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><em>\"Mình đã mua hơn 20 cây từ PlanShop, tất cả đều tươi tốt và đúng mô tả. Đặc biệt là dịch vụ tư vấn rất tận tình, có lần cây bị vàng lá, gọi hotline được hướng dẫn chi tiết và cây đã khỏe lại.\"</em><br><strong>- Chị Lan, Hà Nội</strong></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><em>\"PlanShop đóng gói rất cẩn thận, mình ở Cần Thơ mà cây gửi về vẫn tươi nguyên. Hotline hỗ trợ 24/7 thật sự có ích khi cần tư vấn gấp.\"</em><br><strong>- Anh Tuấn, Cần Thơ</strong></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><em>\"Cửa hàng showroom đẹp, nhân viên am hiểu. Mình đã thiết kế lại toàn bộ ban công nhờ tư vấn của PlanShop. Giờ ban công như một khu vườn nhỏ.\"</em><br><strong>- Chị Hương, TP.HCM</strong></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">📍 BẢN ĐỒ VỊ TRÍ</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><em>[Tại đây bạn có thể nhúng Google Maps cho các địa chỉ cửa hàng]</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>Cách Đến Cửa Hàng Chính Hà Nội:</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>🚌 Xe buýt:</strong> Tuyến 08, 34, 49 - Dừng tại bến XXX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🚗 Ô tô:</strong> Từ trung tâm đi đường YYY, rẽ phải tại ZZZ</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🏍️ Xe máy:</strong> Có chỗ gửi xe miễn phí</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🚶‍♂️ Đi bộ:</strong> 5 phút từ ga tàu điện ngầm TTT</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph -->\n<p><strong>🌿 PlanShop - Nơi Khởi Nguồn Không Gian Xanh 🌿</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>Cảm ơn bạn đã quan tâm đến PlanShop. Chúng tôi luôn sẵn sàng đồng hành cùng bạn trong hành trình tạo dựng không gian sống xanh, mát, đầy sức sống!</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph -->\n<p><strong>📧 Email:</strong> support@planshop.vn<br><strong>📞 Hotline:</strong> 1900 XXX XXX<br><strong>🌐 Website:</strong> https://planshop.vn<br><strong>📍 Địa chỉ:</strong> [Địa chỉ cửa hàng chính]</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Giờ làm việc:</strong> 8:00 - 20:00 (Thứ 2 - Chủ nhật)<br><strong>Hỗ trợ khẩn cấp:</strong> 24/7 qua website chat</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Liên hệ','','publish','closed','closed','','contact','','','2025-08-19 09:38:57','2025-08-19 02:38:57','',0,'http://planshop.local/?page_id=1469',0,'page','',0);
INSERT INTO `wp_posts` VALUES (1471,1,'2025-08-19 09:36:41','2025-08-19 02:36:41','<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🌿 CHÚNG TÔI LUÔN SẴN SÀNG HỖ TRỢ BẠN</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Tại <strong>PlanShop</strong>, chúng tôi cam kết mang đến cho bạn trải nghiệm mua sắm tuyệt vời nhất. Đội ngũ tư vấn viên giàu kinh nghiệm và đam mê cây cảnh của chúng tôi luôn sẵn sàng hỗ trợ bạn 24/7.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">📞 THÔNG TIN LIÊN HỆ</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Hotline Chăm Sóc Khách Hàng</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>📱 Hotline:</strong> 1900 XXX XXX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>⏰ Thời gian:</strong> 8:00 - 20:00 (Thứ 2 - Chủ nhật)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🎯 Hỗ trợ:</strong> Đặt hàng, tư vấn sản phẩm, theo dõi đơn hàng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Hotline Kỹ Thuật - Tư Vấn Chăm Sóc Cây</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>📱 Hotline:</strong> 0909 XXX XXX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>⏰ Thời gian:</strong> 8:00 - 22:00 (Hàng ngày)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🌱 Chuyên về:</strong> Chăm sóc cây, điều trị bệnh, tư vấn kỹ thuật</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Email Hỗ Trợ</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>📧 Tổng đài:</strong> support@planshop.vn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📧 Tư vấn kỹ thuật:</strong> tech@planshop.vn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📧 Hợp tác kinh doanh:</strong> business@planshop.vn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📧 Khiếu nại:</strong> complaint@planshop.vn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>⏱️ Thời gian phản hồi:</strong> Trong vòng 4 giờ (giờ hành chính)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🏢 HỆ THỐNG CỬA HÀNG</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Cửa Hàng Chính - Hà Nội</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>📍 Địa chỉ:</strong> Yên Nghĩa - Hà Đông - Hà Nội - Việt Nam</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>⏰ Giờ mở cửa:</strong> 8:00 - 19:00 (Thứ 2 - Chủ nhật)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📞 Điện thoại:</strong> 024.XXXX.XXXX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🚗 Đỗ xe:</strong> Có khu vực đỗ xe rộng rãi</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🌿 Dịch vụ:</strong> Tư vấn trực tiếp, chăm sóc cây tại chỗ</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">💬 KÊNH HỖ TRỢ TRỰC TUYẾN</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Chat Trực Tuyến</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>🖥️ Website:</strong> Góc phải màn hình trên planshop.vn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>⏰ Hoạt động:</strong> 24/7 với AI ChatBot + nhân viên (8:00-20:00)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🎯 Hỗ trợ:</strong> Tư vấn nhanh, giải đáp thắc mắc tức thì</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Mạng Xã Hội</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>📘 Facebook:</strong> facebook.com/planshop.vietnam<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Tin tức, khuyến mãi, cộng đồng yêu cây</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📸 Instagram:</strong> @planshop_vietnam<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Hình ảnh cây đẹp, tips chăm sóc</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>📺 YouTube:</strong> PlanShop Vietnam<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Video hướng dẫn, livestream tư vấn</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>💬 Zalo OA:</strong> Tìm kiếm \"PlanShop\"<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Tư vấn 1-1, nhận thông báo đơn hàng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">📋 CÁC DỊCH VỤ HỖ TRỢ</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🌱 Tư Vấn Chăm Sóc Cây</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Miễn phí:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Tư vấn chọn cây phù hợp với không gian</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hướng dẫn chăm sóc cơ bản qua điện thoại/chat</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Chẩn đoán bệnh cây qua hình ảnh</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Group Facebook \"Cộng đồng người yêu cây PlanShop\"</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Có phí:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Tư vấn trực tiếp tại nhà (200.000đ/lần, miễn phí trong 10km)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Dịch vụ chăm sóc cây định kỳ</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Thiết kế sân vườn, ban công</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Khóa học chăm sóc cây nâng cao</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>📦 Dịch Vụ Giao Hàng</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Nội thành Hà Nội/TP.HCM:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Giao hàng trong ngày (đặt trước 14:00)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Phí ship: 30.000đ (miễn phí đơn >500.000đ)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Nhân viên chuyên nghiệp, có kinh nghiệm vận chuyển cây</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Toàn quốc:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Thời gian: 2-5 ngày tùy khu vực</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Đóng gói chuyên nghiệp, đảm bảo cây an toàn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bảo hiểm 100% giá trị đơn hàng</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Theo dõi hành trình 24/7</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>🔄 Hậu Mãi &amp; Bảo Hành</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Bảo hành cây 7 ngày</strong> (chết do lỗi vận chuyển/chất lượng)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Hỗ trợ kỹ thuật 3 tháng</strong> miễn phí</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Đổi trả dụng cụ trong 15 ngày</strong> (còn nguyên seal)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Sửa chữa thiết bị</strong> có bảo hành chính hãng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🎯 CÁC TRƯỜNG HỢP LIÊN HỆ</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🛒 Mua Hàng &amp; Đặt Hàng</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Liên hệ khi:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Cần tư vấn chọn cây phù hợp</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Đặt hàng số lượng lớn (>10 cây)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Yêu cầu cây đặc biệt/hiếm</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cần báo giá cho doanh nghiệp</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Thông tin cần cung cấp:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Không gian trồng cây (trong/ngoài nhà, diện tích)</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Điều kiện ánh sáng</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Kinh nghiệm chăm sóc cây</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ngân sách dự kiến</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🌿 Tư Vấn Kỹ Thuật</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Hỗ trợ về:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Cây vàng lá, héo, rụng lá</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Sâu bệnh, nấm mốc</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cách bón phân, tưới nước đúng cách</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tạo dáng, cắt tỉa cây</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Chuẩn bị trước:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Chụp ảnh cây từ nhiều góc độ</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mô tả triệu chứng chi tiết</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Thông tin về cách chăm sóc gần đây</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Điều kiện môi trường (ánh sáng, độ ẩm)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>📞 Khiếu Nại &amp; Góp Ý</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Khi nào cần liên hệ:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Sản phẩm không đúng mô tả</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cây chết/bị bệnh khi nhận hàng</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Dịch vụ không như mong đợi</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Muốn góp ý cải thiện</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Thông tin cần có:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Mã đơn hàng</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ảnh chụp sản phẩm</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mô tả vấn đề cụ thể</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Thời gian phát hiện sự cố</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🤝 HỢP TÁC KINH DOANH</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>👥 Đối Tác Phân Phối</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Chúng tôi tìm kiếm:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Cửa hàng cây cảnh địa phương</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Siêu thị, trung tâm thương mại</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Công ty landscaping</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Nhà thầu xây dựng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Ưu đãi đối tác:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Giá sỉ cạnh tranh</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hỗ trợ marketing</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Đào tạo nhân viên</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bảo hành mở rộng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🏢 Khách Hàng Doanh Nghiệp</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Dịch vụ B2B:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Thiết kế không gian xanh văn phòng</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Cung cấp cây số lượng lớn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hợp đồng chăm sóc dài hạn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tư vấn phong thủy doanh nghiệp</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Quy trình hợp tác:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Khảo sát nhu cầu và không gian</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Đề xuất phương án và báo giá</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ký hợp đồng và triển khai</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bàn giao và hướng dẫn chăm sóc</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hỗ trợ bảo hành và maintain</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">📅 ĐẶT LỊCH HẸN</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🏠 Tư Vấn Tại Nhà</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Đặt lịch:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Online: planshop.vn/dat-lich-tu-van</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hotline: 1900 XXX XXX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Zalo: Nhắn tin \"Đặt lịch tư vấn\"</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Thời gian:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Thứ 2 - Thứ 6: 8:00 - 17:00</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Thứ 7 - Chủ nhật: 8:00 - 12:00</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Đặt trước ít nhất 24 giờ</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>🏢 Thăm Quan Showroom</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Không cần đặt lịch:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Ghé thăm trực tiếp trong giờ mở cửa</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tự do tham quan và tư vấn</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Đặt lịch VIP (khuyến khích):</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Được tư vấn riêng 1-1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Ưu tiên phục vụ</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Miễn phí nước uống và wifi</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">❓ CÂU HỎI THƯỜNG GẶP</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Sản Phẩm</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Q: Cây của PlanShop có được bảo hành không?</strong> A: Có, tất cả cây cảnh được bảo hành 7 ngày chết do lỗi vận chuyển hoặc chất lượng ban đầu. Hỗ trợ tư vañn chăm sóc miễn phí trong 3 tháng.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Q: Làm sao biết cây phù hợp với không gian nhà tôi?</strong> A: Liên hệ hotline tư vấn kỹ thuật, gửi ảnh không gian và chúng tôi sẽ tư vấn cây phù hợp nhất. Hoặc sử dụng tool \"Tìm cây phù hợp\" trên website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Giao Hàng</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Q: Cây có bị hư hại trong quá trình vận chuyển không?</strong> A: Chúng tôi có quy trình đóng gói chuyên nghiệp và bảo hiểm 100% giá trị. Nếu có hư hỏng, chúng tôi hoàn tiền hoặc giao cây mới miễn phí.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Q: Tôi có thể theo dõi đơn hàng như thế nào?</strong> A: SMS tự động, app mobile, hoặc nhập mã vận đơn trên website để theo dõi real-time.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Thanh Toán</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Q: PlanShop hỗ trợ những hình thức thanh toán nào?</strong> A: COD, chuyển khoản, thẻ tín dụng, ví điện tử (MoMo, ZaloPay, VNPay), trả góp qua thẻ tín dụng.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🏆 CAM KẾT CỦA PLANSHOP</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Chất Lượng</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>✅ Cây khỏe mạnh, không mang mầm bệnh</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✅ Nguồn gốc rõ ràng từ các vườn ươm uy tín</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✅ Đóng gói chuyên nghiệp, bảo vệ tối đa</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>✅ Bảo hành rõ ràng, không \"lươn lẹo\"</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Dịch Vụ</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>⭐ Tư vấn tận tình, chuyên nghiệp</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>⭐ Giao hàng đúng hẹn, an toàn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>⭐ Hỗ trợ sau bán hàng chu đáo</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>⭐ Giải quyết khiếu nại nhanh chóng</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\"><strong>Về Giá Cả</strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>💰 Giá cả hợp lý, cạnh tranh</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>💰 Không phát sinh phí ẩn</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>💰 Khuyến mãi thường xuyên</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>💰 Tích điểm đổi quà hấp dẫn</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🌟 ĐÁNH GIÁ TỪ KHÁCH HÀNG</h3>\n<!-- /wp:heading -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><em>\"Mình đã mua hơn 20 cây từ PlanShop, tất cả đều tươi tốt và đúng mô tả. Đặc biệt là dịch vụ tư vấn rất tận tình, có lần cây bị vàng lá, gọi hotline được hướng dẫn chi tiết và cây đã khỏe lại.\"</em><br><strong>- Chị Lan, Hà Nội</strong></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><em>\"PlanShop đóng gói rất cẩn thận, mình ở Cần Thơ mà cây gửi về vẫn tươi nguyên. Hotline hỗ trợ 24/7 thật sự có ích khi cần tư vấn gấp.\"</em><br><strong>- Anh Tuấn, Cần Thơ</strong></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p><em>\"Cửa hàng showroom đẹp, nhân viên am hiểu. Mình đã thiết kế lại toàn bộ ban công nhờ tư vấn của PlanShop. Giờ ban công như một khu vườn nhỏ.\"</em><br><strong>- Chị Hương, TP.HCM</strong></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">📍 BẢN ĐỒ VỊ TRÍ</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><em>[Tại đây bạn có thể nhúng Google Maps cho các địa chỉ cửa hàng]</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\"><strong>Cách Đến Cửa Hàng Chính Hà Nội:</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>🚌 Xe buýt:</strong> Tuyến 08, 34, 49 - Dừng tại bến XXX</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🚗 Ô tô:</strong> Từ trung tâm đi đường YYY, rẽ phải tại ZZZ</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🏍️ Xe máy:</strong> Có chỗ gửi xe miễn phí</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>🚶‍♂️ Đi bộ:</strong> 5 phút từ ga tàu điện ngầm TTT</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph -->\n<p><strong>🌿 PlanShop - Nơi Khởi Nguồn Không Gian Xanh 🌿</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>Cảm ơn bạn đã quan tâm đến PlanShop. Chúng tôi luôn sẵn sàng đồng hành cùng bạn trong hành trình tạo dựng không gian sống xanh, mát, đầy sức sống!</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph -->\n<p><strong>📧 Email:</strong> support@planshop.vn<br><strong>📞 Hotline:</strong> 1900 XXX XXX<br><strong>🌐 Website:</strong> https://planshop.vn<br><strong>📍 Địa chỉ:</strong> [Địa chỉ cửa hàng chính]</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Giờ làm việc:</strong> 8:00 - 20:00 (Thứ 2 - Chủ nhật)<br><strong>Hỗ trợ khẩn cấp:</strong> 24/7 qua website chat</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','LIÊN HỆ - PLANSHOP','','inherit','closed','closed','','1469-revision-v1','','','2025-08-19 09:36:41','2025-08-19 02:36:41','',1469,'http://planshop.local/?p=1471',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1472,1,'2025-08-19 09:38:41','2025-08-19 02:38:41','<p>Về chúng tôi</p>		\n					<h1>Chúng tôi đam mê với công việc của mình</h1>				\n															<img width=\"590\" height=\"610\" src=\"http://planshop.local/wp-content/uploads/2025/03/about-us.jpg\" alt=\"about us\" srcset=\"http://planshop.local/wp-content/uploads/2025/03/about-us.jpg 590w, http://planshop.local/wp-content/uploads/2025/03/about-us-300x310.jpg 300w\" sizes=\"(max-width: 590px) 100vw, 590px\" />															\n					<h2>Chúng tôi nỗ lực cung cấp cho khách hàng chất lượng cao nhất</h2>				\n		<p>Plant Shop được thành lập vào năm 1960 bởi một nhóm những người yêu cây xanh, những người nhận ra tác động tích cực của cây xanh đối với cuộc sống. Dù là thanh lọc không khí, giảm căng thẳng hay đơn giản là tô điểm thêm vẻ đẹp cho môi trường sống, cây xanh không chỉ là vật trang trí mà còn là một lối sống.</p>		\n		<p>“Chúng tôi yêu thích công việc của mình và xây dựng mối quan hệ đối tác với khách hàng để đảm bảo quá trình chuyển đổi số của họ có thể thành công lâu dài.”</p>		\n					<figure><img width=\"100\" height=\"100\" src=\"http://planshop.local/wp-content/uploads/2025/03/testimonial.png\" alt=\"testimonial\" /></figure><h6>Karen Lynn</h6><p>CEO & Co-founder @ Company</p>				\n					<h2>Các giá trị cốt lõi thúc đẩy mọi việc chúng tôi làm việc</h2>				\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M239.1 6.3l-208 78c-18.7 7-31.1 25-31.1 45v225.1c0 18.2 10.3 34.8 26.5 42.9l208 104c13.5 6.8 29.4 6.8 42.9 0l208-104c16.3-8.1 26.5-24.8 26.5-42.9V129.3c0-20-12.4-37.9-31.1-44.9l-208-78C262 2.2 250 2.2 239.1 6.3zM256 68.4l192 72v1.1l-192 78-192-78v-1.1l192-72zm32 356V275.5l160-65v133.9l-160 80z\"></path></svg>				\n									<h4>\n							Đam mê công việc						\n					</h4>\n									<p>\n						Niềm đam mê công việc là sự nhiệt tình và hứng thú với những gì bạn làm.					</p>\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M239.1 6.3l-208 78c-18.7 7-31.1 25-31.1 45v225.1c0 18.2 10.3 34.8 26.5 42.9l208 104c13.5 6.8 29.4 6.8 42.9 0l208-104c16.3-8.1 26.5-24.8 26.5-42.9V129.3c0-20-12.4-37.9-31.1-44.9l-208-78C262 2.2 250 2.2 239.1 6.3zM256 68.4l192 72v1.1l-192 78-192-78v-1.1l192-72zm32 356V275.5l160-65v133.9l-160 80z\"></path></svg>				\n									<h4>\n							Các thành viên nhóm sáng tạo						\n					</h4>\n									<p>\n						Một đội ngũ sáng tạo sẽ thiết kế và thực hiện các chiến dịch và khuyến khích					</p>\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M239.1 6.3l-208 78c-18.7 7-31.1 25-31.1 45v225.1c0 18.2 10.3 34.8 26.5 42.9l208 104c13.5 6.8 29.4 6.8 42.9 0l208-104c16.3-8.1 26.5-24.8 26.5-42.9V129.3c0-20-12.4-37.9-31.1-44.9l-208-78C262 2.2 250 2.2 239.1 6.3zM256 68.4l192 72v1.1l-192 78-192-78v-1.1l192-72zm32 356V275.5l160-65v133.9l-160 80z\"></path></svg>				\n									<h4>\n							Giải pháp đổi mới						\n					</h4>\n									<p>\n						Sử dụng hoàn toàn các khái niệm tìm ra những cách mới để sử dụng các khái niệm hiện có					</p>\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M239.1 6.3l-208 78c-18.7 7-31.1 25-31.1 45v225.1c0 18.2 10.3 34.8 26.5 42.9l208 104c13.5 6.8 29.4 6.8 42.9 0l208-104c16.3-8.1 26.5-24.8 26.5-42.9V129.3c0-20-12.4-37.9-31.1-44.9l-208-78C262 2.2 250 2.2 239.1 6.3zM256 68.4l192 72v1.1l-192 78-192-78v-1.1l192-72zm32 356V275.5l160-65v133.9l-160 80z\"></path></svg>				\n									<h4>\n							Sản phẩm chất lượng						\n					</h4>\n									<p>\n						Chất lượng sản phẩm đề cập đến mức độ sản phẩm làm hài lòng khách hàng của chúng tôi					</p>\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M239.1 6.3l-208 78c-18.7 7-31.1 25-31.1 45v225.1c0 18.2 10.3 34.8 26.5 42.9l208 104c13.5 6.8 29.4 6.8 42.9 0l208-104c16.3-8.1 26.5-24.8 26.5-42.9V129.3c0-20-12.4-37.9-31.1-44.9l-208-78C262 2.2 250 2.2 239.1 6.3zM256 68.4l192 72v1.1l-192 78-192-78v-1.1l192-72zm32 356V275.5l160-65v133.9l-160 80z\"></path></svg>				\n									<h4>\n							Sự hài lòng của khách hàng						\n					</h4>\n									<p>\n						Khách hàng hài lòng vì dịch vụ chăm sóc khách hàng					</p>\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M239.1 6.3l-208 78c-18.7 7-31.1 25-31.1 45v225.1c0 18.2 10.3 34.8 26.5 42.9l208 104c13.5 6.8 29.4 6.8 42.9 0l208-104c16.3-8.1 26.5-24.8 26.5-42.9V129.3c0-20-12.4-37.9-31.1-44.9l-208-78C262 2.2 250 2.2 239.1 6.3zM256 68.4l192 72v1.1l-192 78-192-78v-1.1l192-72zm32 356V275.5l160-65v133.9l-160 80z\"></path></svg>				\n									<h4>\n							Giao diện đơn giản						\n					</h4>\n									<p>\n						Sự đơn giản được sử dụng một cách lỏng lẻo để ám chỉ nhu cầu giảm thiểu một quá trình					</p>\n					<h2>Sứ mệnh của chúng tôi</h2>				\n		<p>Sứ mệnh của chúng tôi là góp phần làm cho thế giới xanh hơn, từng cây một. Chúng tôi nỗ lực cung cấp cho khách hàng những cây trồng và sản phẩm chăm sóc cây trồng chất lượng cao nhất, cùng với kiến thức và sự hỗ trợ để giúp họ phát triển bền vững.</p>		\n							<ul>\n							<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M504 256c0 136.967-111.033 248-248 248S8 392.967 8 256 119.033 8 256 8s248 111.033 248 248zM227.314 387.314l184-184c6.248-6.248 6.248-16.379 0-22.627l-22.627-22.627c-6.248-6.249-16.379-6.249-22.628 0L216 308.118l-70.059-70.059c-6.248-6.248-16.379-6.248-22.628 0l-22.627 22.627c-6.248 6.248-6.248 16.379 0 22.627l104 104c6.249 6.249 16.379 6.249 22.628.001z\"></path></svg>						\n										Chất lượng và sự đa dạng\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M504 256c0 136.967-111.033 248-248 248S8 392.967 8 256 119.033 8 256 8s248 111.033 248 248zM227.314 387.314l184-184c6.248-6.248 6.248-16.379 0-22.627l-22.627-22.627c-6.248-6.249-16.379-6.249-22.628 0L216 308.118l-70.059-70.059c-6.248-6.248-16.379-6.248-22.628 0l-22.627 22.627c-6.248 6.248-6.248 16.379 0 22.627l104 104c6.249 6.249 16.379 6.249 22.628.001z\"></path></svg>						\n										Thực hành bền vững\n									</li>\n						</ul>\n							<ul>\n							<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M504 256c0 136.967-111.033 248-248 248S8 392.967 8 256 119.033 8 256 8s248 111.033 248 248zM227.314 387.314l184-184c6.248-6.248 6.248-16.379 0-22.627l-22.627-22.627c-6.248-6.249-16.379-6.249-22.628 0L216 308.118l-70.059-70.059c-6.248-6.248-16.379-6.248-22.628 0l-22.627 22.627c-6.248 6.248-6.248 16.379 0 22.627l104 104c6.249 6.249 16.379 6.249 22.628.001z\"></path></svg>						\n										Hướng dẫn chuyên gia\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M504 256c0 136.967-111.033 248-248 248S8 392.967 8 256 119.033 8 256 8s248 111.033 248 248zM227.314 387.314l184-184c6.248-6.248 6.248-16.379 0-22.627l-22.627-22.627c-6.248-6.249-16.379-6.249-22.628 0L216 308.118l-70.059-70.059c-6.248-6.248-16.379-6.248-22.628 0l-22.627 22.627c-6.248 6.248-6.248 16.379 0 22.627l104 104c6.249 6.249 16.379 6.249 22.628.001z\"></path></svg>						\n										Đội ngũ giàu kinh nghiệm\n									</li>\n						</ul>\n															<img width=\"590\" height=\"610\" src=\"http://planshop.local/wp-content/uploads/2025/03/our-mission.jpg\" alt=\"our mission\" srcset=\"http://planshop.local/wp-content/uploads/2025/03/our-mission.jpg 590w, http://planshop.local/wp-content/uploads/2025/03/our-mission-300x310.jpg 300w\" sizes=\"(max-width: 590px) 100vw, 590px\" />															\n		<p>Mọi ý kiến của bạn là cơ hội để chúng tôi tốt hơn</p>		\n					<h1>Chúng tôi chỉ cách bạn một tin nhắn</h1>				\n					<h2>Gửi tin nhắn cho chúng tôi\n</h2>				\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M497.39 361.8l-112-48a24 24 0 0 0-28 6.9l-49.6 60.6A370.66 370.66 0 0 1 130.6 204.11l60.6-49.6a23.94 23.94 0 0 0 6.9-28l-48-112A24.16 24.16 0 0 0 122.6.61l-104 24A24 24 0 0 0 0 48c0 256.5 207.9 464 464 464a24 24 0 0 0 23.4-18.6l24-104a24.29 24.29 0 0 0-14.01-27.6z\"></path></svg>				\n									<h4>\n							Số điện thoại						\n					</h4>\n									<p>\n						0386849210					</p>\n				<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M502.3 190.8c3.9-3.1 9.7-.2 9.7 4.7V400c0 26.5-21.5 48-48 48H48c-26.5 0-48-21.5-48-48V195.6c0-5 5.7-7.8 9.7-4.7 22.4 17.4 52.1 39.5 154.1 113.6 21.1 15.4 56.7 47.8 92.2 47.6 35.7.3 72-32.8 92.3-47.6 102-74.1 131.6-96.3 154-113.7zM256 320c23.2.4 56.6-29.2 73.4-41.4 132.7-96.3 142.8-104.7 173.4-128.7 5.8-4.5 9.2-11.5 9.2-18.9v-19c0-26.5-21.5-48-48-48H48C21.5 64 0 85.5 0 112v19c0 7.4 3.4 14.3 9.2 18.9 30.6 23.9 40.7 32.4 173.4 128.7 16.8 12.2 50.2 41.8 73.4 41.4z\"></path></svg>				\n									<h4>\n							Email						\n					</h4>\n									<p>\n						plantshophotline@gmail.com					</p>\n				<svg aria-hidden=\"true\" viewBox=\"0 0 384 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M172.268 501.67C26.97 291.031 0 269.413 0 192 0 85.961 85.961 0 192 0s192 85.961 192 192c0 77.413-26.97 99.031-172.268 309.67-9.535 13.774-29.93 13.773-39.464 0zM192 272c44.183 0 80-35.817 80-80s-35.817-80-80-80-80 35.817-80 80 35.817 80 80 80z\"></path></svg>				\n									<h4>\n							Địa chỉ						\n					</h4>\n									<p>\n						Yên Nghĩa - Hà Đông - Hà Nội - Việt Nam					</p>\n		<form id=\"wpforms-form-13\" data-formid=\"13\" method=\"post\" enctype=\"multipart/form-data\" action=\"/wp-admin/admin-ajax.php\" data-token=\"7a362ac39640644b90e58e2d755578dc\" data-token-time=\"1752666525\"><noscript>Vui lòng bật JavaScript trong trình duyệt của bạn để hoàn thành Form này.</noscript>Vui lòng bật JavaScript trong trình duyệt của bạn để hoàn thành Form này.<lab