INSERT INTO `wp_yith_wcas_data_index_lookup` VALUES (1279,'Dầu Neem','<h4>Sự miêu tả</h4>\r\nDầu Neem Bonide được khuyến nghị sử dụng cho các bà mẹ trồng cây cần một sản phẩm tự nhiên và đa năng để chăm sóc cây trồng. Được chiết xuất từ hạt Neem, dầu Neem tiêu diệt sâu bệnh, trứng và ấu trùng ngay khi tiếp xúc. Sản phẩm có hiệu quả trong việc điều trị nhiều loại sâu bệnh, bao gồm nhện đỏ, rệp sáp và ruồi muỗi. Sản phẩm cũng điều trị nhiều loại bệnh nấm như đốm lá và phấn trắng.\r\n\r\nThường được sử dụng cho cây trồng trong nhà, hoa hồng, hoa, rau, thảo mộc, gia vị, cây cối, thảm cỏ và cây bụi. Luôn làm theo hướng dẫn trên nhãn.\r\n\r\n&nbsp;\r\n\r\n<strong>Giới thiệu về Bonide:</strong>\r\n\r\nBonide là một doanh nghiệp gia đình được thành lập năm 1926 bởi hai anh em George và James Wurz. Công ty đã phát triển và trở thành một trong những công ty hàng đầu đáng tin cậy và được kính trọng nhất trong lĩnh vực kiểm soát dịch hại và làm vườn. Danh mục sản phẩm làm vườn tổng hợp và hữu cơ đa dạng của họ rất nổi tiếng và được yêu thích, và chúng tôi tại Bloomscape tự hào được hỗ trợ Bonide và chia sẻ sản phẩm của họ với khách hàng.\r\n\r\n<strong>Thông số kỹ thuật:</strong>\r\n<ul>\r\n 	<li>Bình xịt sẵn sàng sử dụng, 32 Fl oz</li>\r\n</ul>\r\n&nbsp;\r\n\r\n<em>Xin lưu ý: Sản phẩm này không được giảm giá và sẽ được vận chuyển riêng khi đặt hàng cây.</em>','Dầu Neem Bonide là thuốc trừ sâu, diệt mạt và diệt nấm đa năng cho làm vườn hữu cơ. Dầu neem rất tốt cho người trồng trọt để xử lý sâu bệnh đang hoạt động và ngăn ngừa sự bùng phát trong tương lai.','http://planshop.local/product/dau-neem/','','a:2:{s:5:\"small\";s:89:\"http://planshop.local/wp-content/uploads/2025/08/bloomscape_neem-oil-scaled-1-150x150.jpg\";s:3:\"big\";s:89:\"http://planshop.local/wp-content/uploads/2025/08/bloomscape_neem-oil-scaled-1-300x300.jpg\";}',393000.0000,394000.0000,1,1,40,1,1,5,0,'product',0,'simple','a:2:{i:0;i:43;i:1;i:39;}','a:0:{}','vi',0,'','a:0:{}',0.00);
INSERT INTO `wp_yith_wcas_data_index_lookup` VALUES (1286,'Xà phòng diệt côn trùng','<h4>Sự miêu tả</h4>\r\nDiệt trừ nhiều loại sâu bệnh bằng Xà phòng diệt côn trùng Garden Safe®. Loại bình xịt pha sẵn này có thể tiêu diệt rệp vừng, rệp sáp, ve, rầy, bọ nhảy, rệp sáp, bọ trĩ và bọ phấn trắng ngay khi tiếp xúc. Có thể xịt lên rau quả ăn được cho đến ngày thu hoạch.\r\n\r\nTừ năm 2002, thương hiệu Garden Safe® đã cung cấp các sản phẩm, bao gồm các công thức có nguồn gốc tự nhiên và thực vật, cho những người trồng trọt muốn kiểm soát sâu bệnh hại cây trồng mà không cần hóa chất truyền thống. Những người làm vườn hữu cơ tin tưởng Garden Safe® giúp việc kiểm soát sâu bệnh trong vườn trở nên đơn giản – và để thiên nhiên lo liệu phần còn lại.\r\n\r\nLuôn làm theo hướng dẫn trên nhãn.\r\n\r\n<strong>Thông số kỹ thuật:</strong>\r\n<ul>\r\n 	<li>Bình xịt sẵn sàng sử dụng, 32 Fl oz</li>\r\n</ul>\r\n&nbsp;\r\n\r\n<em><strong>Xin lưu ý:</strong> Sản phẩm này không được giảm giá và sẽ được vận chuyển riêng khi đặt hàng cây.</em>','Tiêu diệt côn trùng ngay khi tiếp xúc với Xà phòng Diệt Côn Trùng Garden Safe® pha sẵn. Sản phẩm này rất tiện lợi để sử dụng trong nhà, giúp diệt trừ nhiều loại côn trùng gây hại, bao gồm rệp vừng, mạt và rệp sáp. Xà phòng diệt côn trùng có thể được sử dụng cho cả cây trồng trong nhà và ngoài trời. Thích hợp cho làm vườn hữu cơ, có thể sử dụng đến tận ngày thu hoạch.','http://planshop.local/product/xa-phong-diet-con-trung/','','a:2:{s:5:\"small\";s:98:\"http://planshop.local/wp-content/uploads/2025/08/bloomscape_insecticidal-soap-scaled-1-150x150.jpg\";s:3:\"big\";s:98:\"http://planshop.local/wp-content/uploads/2025/08/bloomscape_insecticidal-soap-scaled-1-300x300.jpg\";}',393000.0000,393000.0000,0,1,25,1,0,0,1,'product',0,'simple','a:2:{i:0;i:43;i:1;i:39;}','a:0:{}','vi',0,'','a:0:{}',0.00);
INSERT INTO `wp_yith_wcas_data_index_lookup` VALUES (1299,'Bình tưới nước','<h4><span>Sự miêu tả</span></h4>\r\n<span>Bình tưới nước màu xanh lá cây đậm tuyệt đẹp này lý tưởng để tưới cho bất kỳ loại cây nào trong bộ sưu tập của bạn. Được làm từ nhựa bền và có thể tái chế 100%, bạn sẽ có bình tưới này cho nhiều mùa. Bình chứa 1,5 lít nước và có đầu nối hình hoa hồng có thể tháo rời, giúp bạn có thể tưới cây cả trong nhà lẫn ngoài trời. Bình tưới nước duyên dáng này là sự bổ sung hoàn hảo cho lối sống yêu cây xanh của bạn. Nó cũng là một món quà tuyệt vời cho người yêu cây cối trong cuộc sống của bạn.</span>\r\n\r\n<strong><span>Thông số kỹ thuật:</span></strong>\r\n<ul>\r\n 	<li><span>Kích thước: 14” x 5” x 7”</span></li>\r\n 	<li><span>Dung tích: 1,5 lít</span></li>\r\n 	<li><span>Chất liệu: 100% nhựa có thể tái chế</span></li>\r\n</ul>\r\n<em><span>Xin lưu ý: Sản phẩm này không được giảm giá và sẽ được vận chuyển riêng khi đặt hàng cây.</span></em>','Bình tưới nước xinh xắn này là một dụng cụ không thể thiếu trong bộ dụng cụ chăm sóc cây trồng của bạn. Với màu xanh lá cây đậm tuyệt đẹp, mỗi bình chứa được 1,5 lít nước và được làm từ 100% nhựa tái chế. Với đầu tưới có thể tháo rời và thiết kế truyền thống, sản phẩm thiết yếu cổ điển này bổ sung cả hình thức lẫn chức năng cho bộ dụng cụ làm vườn của bạn.','http://planshop.local/product/binh-tuoi-nuoc/','','a:2:{s:5:\"small\";s:96:\"http://planshop.local/wp-content/uploads/2025/08/bloomscape_watering-can_4b-scaled-1-150x150.jpg\";s:3:\"big\";s:96:\"http://planshop.local/wp-content/uploads/2025/08/bloomscape_watering-can_4b-scaled-1-300x300.jpg\";}',759999.0000,765000.0000,1,1,68,1,0,0,0,'product',0,'simple','a:2:{i:0;i:39;i:1;i:41;}','a:0:{}','vi',0,'','a:0:{}',0.00);
INSERT INTO `wp_yith_wcas_data_index_lookup` VALUES (1310,'Đèn trồng cây nhỏ','<h4>Sự miêu tả</h4>\r\nMang thiên nhiên vào cả những nơi tối tăm nhất trong nhà bạn với Đèn Trồng Cây Nhỏ Gọn này. Đèn treo này cho phép bạn tạo điều kiện ánh sáng tối ưu cho cây trồng trong nhà, dù bạn có căn hộ thiếu sáng hay chỉ là một góc tối cần được làm đẹp. Chúng tôi khuyên dùng đèn trồng cây này cho các loại cây vừa và nhỏ hoặc cây lớn hơn được coi là cần ít ánh sáng (cây lưỡi hổ, cây kim tiền, cây huyết dụ, v.v.).\r\n\r\nĐược thiết kế sử dụng quang phổ quang hợp có độ chính xác cao, đèn trồng cây nhỏ gọn này tạo ra chất lượng ánh sáng chuyên nghiệp và dễ dàng lắp đặt bằng phần cứng đi kèm. Với tuổi thọ 90.000 giờ và 15 năm sử dụng, đèn này chính là thứ bạn cần để cây trồng phát triển khỏe mạnh, tươi tốt.\r\n\r\n<strong>Giới thiệu về Soltech Solutions:</strong>\r\n\r\nSoltech Solutions là một doanh nghiệp nhỏ tư nhân cam kết tạo việc làm và hỗ trợ nền kinh tế địa phương. Tất cả đèn trồng cây của họ đều được thiết kế, lắp ráp và sản xuất tại Mỹ, tại văn phòng của họ ở Bethlehem, Pennsylvania. Họ tin vào sức mạnh biến đổi và chữa lành của thiên nhiên và mong muốn mọi người đều được trải nghiệm niềm vui khi có cây xanh trong nhà, đó là lý do tại sao chúng tôi tự hào bán đèn trồng cây của họ.\r\n\r\n<strong>Thông số kỹ thuật:</strong>\r\n<ul>\r\n 	<li>Kích thước: Đèn: 5 ½” (D) x 4” (S), Dây: 15′</li>\r\n 	<li>Công suất: 20W</li>\r\n</ul>\r\n<em><strong>Xin lưu ý:</strong> Sản phẩm này không được giảm giá và sẽ được vận chuyển riêng khi đặt hàng cây.</em>','Không gian của bạn đang thiếu ánh sáng cần thiết cho cây trồng phát triển? Hãy tạo điều kiện ánh sáng tối ưu cho cây trồng trong nhà với Đèn Trồng Cây Nhỏ Gọn thời trang này. Đèn trồng cây treo 20W này kết hợp hoàn hảo với các loại cây cỡ nhỏ đến trung bình, hoặc các loại cây lớn hơn, cần ít ánh sáng','http://planshop.local/product/den-trong-cay-nho/','','a:2:{s:5:\"small\";s:96:\"http://planshop.local/wp-content/uploads/2025/08/bloomscape_product_soltech-sm-black-150x150.jpg\";s:3:\"big\";s:96:\"http://planshop.local/wp-content/uploads/2025/08/bloomscape_product_soltech-sm-black-300x300.jpg\";}',3979999.0000,3979999.0000,0,1,10,1,0,0,0,'product',0,'variable','a:2:{i:0;i:39;i:1;i:150;}','a:1:{i:0;i:152;}','vi',0,'','a:0:{}',0.00);
